begin;
create temporary table kl_cyber_results(name text,passed boolean);
do $$
declare u uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()]; sid uuid;tid uuid;cid uuid;i int;res jsonb;bad boolean;begin
 for i in 1..7 loop insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(u[i],u[i]::text||'@example.invalid',now(),false);end loop;
 perform set_config('request.jwt.claim.sub',u[1]::text,true);
 sid:=public.kl_submit_tagged('KL-CYBER-TEST-'||gen_random_uuid()||' #Pragmatik','','Synthetic context for isolated reaction testing.','de','normal','{}',array['Slang','#Pragmatik']);
 if not exists(select 1 from public.kl_samples where id=sid and hashtags @> array['slang','pragmatik','normal'] and cardinality(hashtags)=3) then raise exception 'FAIL hashtag normalize/extract';end if;
 insert into kl_cyber_results values('hashtags normalized, extracted and deduplicated',true);
 update public.kl_samples set status='approved',final_tag='normal',approved_at=now() where id=sid;
 perform set_config('request.jwt.claim.sub',u[2]::text,true);
 perform public.kl_react(sid,1,null);perform public.kl_react(sid,-1,'label_disputed');
 if (select count(*) from public.kl_likes where sample_id=sid)<>1 then raise exception 'FAIL mutually exclusive';end if;
 perform public.kl_react(sid,1,null);
 perform set_config('request.jwt.claim.sub',u[3]::text,true);perform public.kl_react(sid,1,null);
 for i in 4..6 loop perform set_config('request.jwt.claim.sub',u[i]::text,true);res:=public.kl_react(sid,-1,'context_incomplete');end loop;
 if not exists(select 1 from public.kl_samples where id=sid and status='approved') then raise exception 'FAIL exactly 60 percent withdrawn';end if;
 insert into kl_cyber_results values('exactly 3/5 dislikes remains published',true);
 perform set_config('request.jwt.claim.sub',u[7]::text,true);res:=public.kl_react(sid,-1,'label_disputed');
 if not exists(select 1 from public.kl_samples where id=sid and status='withdrawn' and withdrawal_reason='community_disapproval' and (withdrawal_snapshot->>'negative')::int=4 and (withdrawal_snapshot->>'total')::int=6 and withdrawn_at is not null) then raise exception 'FAIL above60 not archived or snapshot lost';end if;
 insert into kl_cyber_results values('4/6 dislikes archives with immutable vote snapshot and reason',true);
 bad:=false;begin perform public.kl_react(sid,1,null);exception when others then if sqlerrm='reactions_closed' then bad:=true;else raise;end if;end;
 if not bad then raise exception 'FAIL archived reactions open';end if;insert into kl_cyber_results values('archived reactions frozen',true);
 cid:=public.kl_comment(sid,'Discussion continues after withdrawal.');
 if not exists(select 1 from public.kl_comments where id=cid) then raise exception 'FAIL archive comments denied';end if;insert into kl_cyber_results values('withdrawn samples retain discussion',true);
 perform set_config('request.jwt.claim.sub',u[1]::text,true);
 tid:=public.kl_submit_tagged('KL-TREND-TEST-'||gen_random_uuid(),'','Synthetic context for trend window testing.','de','ambiguous','{}',array['trendtestunique']);
 for i in 2..5 loop perform set_config('request.jwt.claim.sub',u[i]::text,true);perform public.kl_vote(tid,'ambiguous','Independent synthetic annotation.');end loop;
 res:=public.kl_stats();
 if not exists(select 1 from jsonb_array_elements(res->'trending') x where x->>'hashtag'='trendtestunique' and (x->>'annotations')::int=4 and (x->>'samples')::int=1) then raise exception 'FAIL hashtag annotation aggregation';end if;
 insert into kl_cyber_results values('trending counts real annotations and distinct samples',true);
 update public.kl_votes set created_at=now()-interval '8 days' where sample_id=tid;
 if exists(select 1 from jsonb_array_elements(public.kl_stats()->'trending') x where x->>'hashtag'='trendtestunique') then raise exception 'FAIL old annotations count';end if;
 insert into kl_cyber_results values('trending excludes events outside seven days',true);
 bad:=false;begin perform public.kl_submit_tagged('KL-INVALID-'||gen_random_uuid(),'','Synthetic invalid hashtag test context.','de','normal','{}',array['<script>']);exception when others then if sqlerrm='invalid_hashtag' then bad:=true;else raise;end if;end;
 if not bad then raise exception 'FAIL invalid hashtag accepted';end if;
 insert into kl_cyber_results values('invalid hashtag rejected',true);
 if has_table_privilege('authenticated','public.kl_likes','INSERT') or has_table_privilege('anon','public.kl_samples','UPDATE') then raise exception 'FAIL direct mutation';end if;
 insert into kl_cyber_results values('new reactions remain server controlled',true);
end;$$;
select * from kl_cyber_results;
rollback;
